<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';
require_login();
$config=__DIR__.'/config/database.php';
if(!is_file($config)){http_response_code(503);exit('Database configuration is not ready.');}
require $config;
$bid=current_business_id();
$q=$pdo->prepare('SELECT product_code,product_name,main_category,category,unit,selling_price FROM products WHERE business_id=? AND is_active=1 ORDER BY product_name');
$q->execute([$bid]);
$products=$q->fetchAll(PDO::FETCH_ASSOC);
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Price List • MeroKhata</title><link rel="stylesheet" href="assets/css/style.css"><style>.accountbar{font-size:12px;margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,.18)}.accountbar a{color:#fff}.price-search{max-width:720px}.price-search input{font-size:18px;padding:13px}.price-card{margin-top:14px;padding:20px;border:1px solid #dbe3ec;border-radius:12px;background:#f8fbff;display:none}.price-card.show{display:block}.price-name{font-size:24px;font-weight:700}.price-value{font-size:32px;font-weight:800;margin-top:8px}.price-meta{margin-top:6px;color:#64748b}.table-wrap{overflow:auto}.muted2{color:#64748b;font-size:13px}</style></head><body><aside class="sidebar"><div class="brand">MeroKhata</div><div class="subbrand">Online Database</div><div class="nav"><button>Dashboard</button><button>Products</button><button>Suppliers</button><button>Purchase Entry</button><button>Party / Customer</button><button>Sales & Billing</button><button>Sales Register</button><button>Sales Reports</button><button>Stock / Inventory</button><button class="active">Price List</button><button>Price Comparison</button></div><div class="accountbar"><?=e($_SESSION['name']??'User')?> · <?=e(ucfirst($_SESSION['role']??''))?><br><a href="logout.php">Logout</a></div></aside><main class="main"><div class="topbar"><h1>Price List</h1><div class="muted">Quick Selling Price Lookup</div></div><section class="panel active"><div class="box price-search"><h3>Find Selling Price</h3><label>Product Name / Product Code<input id="search" list="productChoices" autocomplete="off" placeholder="Type product name or code..." autofocus></label><datalist id="productChoices"><?php foreach($products as $p):?><option value="<?=e($p['product_code'].' — '.$p['product_name'])?>"></option><?php endforeach;?></datalist><div id="priceCard" class="price-card"><div id="pName" class="price-name"></div><div id="pPrice" class="price-value"></div><div id="pMeta" class="price-meta"></div></div><p class="muted2">Start typing a product name or code. Matching products will appear below immediately.</p></div><div class="box"><h3>All Selling Prices</h3><div class="table-wrap"><table><thead><tr><th>Code</th><th>Product</th><th>Category</th><th>Unit</th><th>Selling Price</th></tr></thead><tbody id="priceRows"><?php foreach($products as $p):?><tr data-key="<?=e(strtolower($p['product_code'].' '.$p['product_name']))?>"><td><?=e($p['product_code'])?></td><td><?=e($p['product_name'])?></td><td><?=e(trim(($p['main_category']??'').' / '.($p['category']??''),' /'))?></td><td><?=e($p['unit'])?></td><td><b>Rs. <?=number_format((float)$p['selling_price'],2)?></b></td></tr><?php endforeach;?></tbody></table></div></div></section></main><script>const products=<?=json_encode($products,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const s=document.getElementById('search'),card=document.getElementById('priceCard'),pn=document.getElementById('pName'),pp=document.getElementById('pPrice'),pm=document.getElementById('pMeta'),rows=[...document.querySelectorAll('#priceRows tr')];function norm(v){return String(v||'').trim().toLowerCase()}function update(){const q=norm(s.value),clean=q.split(' — ')[0];rows.forEach(r=>r.style.display=!q||r.dataset.key.includes(q)||r.dataset.key.includes(clean)?'':'none');if(!q){card.classList.remove('show');return}let p=products.find(x=>norm(x.product_code+' — '+x.product_name)===q)||products.find(x=>norm(x.product_code)===q)||products.find(x=>norm(x.product_name)===q);if(!p){const matches=products.filter(x=>norm(x.product_code+' '+x.product_name).includes(q));if(matches.length===1)p=matches[0]}if(p){pn.textContent=p.product_name;pp.textContent='Rs. '+Number(p.selling_price||0).toFixed(2);pm.textContent=p.product_code+' • '+(p.unit||'')+' • '+[p.main_category,p.category].filter(Boolean).join(' / ');card.classList.add('show')}else card.classList.remove('show')}s.addEventListener('input',update);s.addEventListener('change',update);</script><script src="assets/js/online-nav.js"></script></body></html>